"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[766],{31733:e=>{e.exports=JSON.parse('{"functions":[{"name":"raycast","desc":"Performs a raycast against the physical world.\\n\\nThe ray is constructed using an origin and a direction, which is then scaled by the provided distance.\\nAn exclusion list can be provided to ignore specific instances during the raycast calculation.\\n\\n### Example Usage:\\n```lua\\nlocal result = physics.raycast(Vector3.new(0, 10, 0), Vector3.new(0, -1, 0), 100, { workspace.BasePlate })\\nif result then\\n    print(\\"Hit \\" .. result.instance.Name .. \\" at \\" .. tostring(result.position))\\nend\\n```","params":[{"name":"origin","desc":"The starting point of the ray.","lua_type":"vector"},{"name":"direction","desc":"The unit direction of the ray.","lua_type":"vector"},{"name":"distance","desc":"The maximum distance the ray should travel.","lua_type":"number"},{"name":"ignoreList","desc":"An array containing instances that the ray should ignore.","lua_type":"{Instance}"}],"returns":[{"desc":"A table containing hit information, or nil if no hit occurred.","lua_type":"RaycastResult?"}],"function_type":"static","source":{"line":29,"path":"src/libraries/physics.luau"}}],"properties":[],"types":[{"name":"RaycastResult","desc":"","fields":[{"name":"distance","lua_type":"number","desc":"The distance from the origin to the hit position."},{"name":"hit_successful","lua_type":"boolean","desc":"Whether the raycast successfully hit a surface."},{"name":"position","lua_type":"vector","desc":"The world position where the ray hit."},{"name":"instance","lua_type":"Instance?","desc":"The Instance that was hit by the ray."}],"source":{"line":41,"path":"src/libraries/physics.luau"}}],"name":"physics","desc":"The physics library provides access to the world\'s physical state, allowing for spatial queries such as raycasting.","tags":["Library"],"source":{"line":6,"path":"src/libraries/physics.luau"}}')}}]);